<?php
/** Published branch details with actual configured hours. @package Flavor */
defined( 'ABSPATH' ) || exit;
get_header();
while ( have_posts() ) : the_post(); $b = \Flavor\UI_Pages::branch( get_the_ID() ); ?>
<div class="flavor-container flavor-branch-single"><?php \Flavor\UI_Pages::breadcrumb( get_the_title() ); ?><div class="flavor-ui-page-head"><div><span class="flavor-ui-overline"><?php echo esc_html( $b['city'] ?? '' ); ?></span><h1><?php the_title(); ?></h1></div></div><div class="flavor-contact-layout"><section class="flavor-ui-panel"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'large', array( 'class' => 'flavor-branch-single__photo' ) ); } ?><h2><?php esc_html_e( 'اطلاعات این شعبه', 'flavor' ); ?></h2><p class="flavor-branch-card__address"><?php echo esc_html( $b['address'] ?? '' ); ?></p><?php if ( ! empty( $b['phone'] ) ) : ?><a class="flavor-branch-card__phone" href="<?php echo esc_url( \Flavor\UI_Pages::tel( $b['phone'] ) ); ?>"><?php \Flavor\UI::icon( 'phone', 18 ); ?><bdi><?php echo esc_html( \Flavor\Bespoke_Demos::digits( $b['phone'] ) ); ?></bdi></a><?php endif; ?><div class="flavor-branch-card__modes"><?php foreach ( $b['modes'] ?? array() as $mode ) : ?><span class="flavor-ui-tag"><?php echo esc_html( \Flavor\UI::mode_labels()[ $mode ] ); ?></span><?php endforeach; ?></div><?php \Flavor\UI_Pages::content(); ?><div class="flavor-branch-card__actions"><a class="flavor-btn flavor-btn--primary" href="<?php echo esc_url( add_query_arg( 'flavor_branch', get_the_ID(), \Flavor\UI::url( 'menu' ) ) ); ?>"><?php esc_html_e( 'منو و انتخاب این شعبه', 'flavor' ); ?></a><?php if ( ! empty( $b['map'] ) ) : ?><a class="flavor-ui-text-link" href="<?php echo esc_url( $b['map'] ); ?>" target="_blank" rel="noopener noreferrer"><?php esc_html_e( 'موقعیت ثبت‌شده در نقشه', 'flavor' ); ?></a><?php endif; ?></div></section><aside class="flavor-ui-panel"><span class="flavor-ui-overline"><?php esc_html_e( 'برنامهٔ ثبت‌شدهٔ شعبه', 'flavor' ); ?></span><h2><?php esc_html_e( 'ساعات فعالیت', 'flavor' ); ?></h2><?php \Flavor\UI_Pages::render_hours( get_the_ID() ); ?><p class="flavor-ui-note"><?php esc_html_e( 'ساعات با تعطیلی موردی یا برنامهٔ خاص ممکن است تغییر کنند؛ پیش از مراجعه هماهنگ کنید.', 'flavor' ); ?></p><?php if ( \Flavor\UI::reservation_available( get_the_ID() ) ) : ?><a class="flavor-btn flavor-btn--outline" href="<?php echo esc_url( add_query_arg( 'flavor_branch', get_the_ID(), \Flavor\UI::url( 'reservation' ) ) ); ?>"><?php esc_html_e( 'بررسی ظرفیت رزرو', 'flavor' ); ?></a><?php endif; ?></aside></div></div>
<?php endwhile; get_footer(); ?>
